                                order.append(value)
                            counts[value] += 1
                        motif.append(max(order, key=lambda value: counts[value]))

                    errors = sum(
                        line[a + 1 + t] != motif[t % period]
                        for t in range(length)
                    )
                    if errors > max(2, length // 8):
                        continue

                    key = (length, -errors, -period)
                    if best_key is None or key > best_key:
                        best_key = key
                        best_data = (a, b, motif, period)

        if best_data is None:
